        title:isExam?(french?`${String(globalLevel).padStart(3,'0')} · Examen de maîtrise : ${unitTitle}`:`${String(globalLevel).padStart(3,'0')} · ${unitTitle} mastery exam`):isGame?`${String(globalLevel).padStart(3,'0')} · ${unitTitle} · ${topic[0].split(': ').at(-1)} · ${task}`:title,
        summary:`${displaySubject} · ${unitTitle} · ${french?'Objectif':'Task'} : ${task}.`,
