      button.innerHTML=`<span class="subject-option-icon"><img src="assets/icons/${subject==='Geology'||subject==='Earth Science and Universe'?'earth-energy.svg':'book-open.svg'}" alt=""></span><span class="subject-option-text"><strong>${subjectLabel}</strong><small>${french?'LEÇONS · JEU · EXAMEN':'LESSONS · GAME · EXAM'}</small></span><span class="subject-option-arrow">↗</span>`;
